/**
 * AI 生成并优化的高清 Match-3 特效图块素材库 (Base64 内嵌免异步无损加载)
 */
export class SpecialTileAssets {
    public static readonly B64_HORIZONTAL = 'data:image/png;base64,' +
        '';

    public static readonly B64_VERTICAL = 'data:image/png;base64,' +
        '';

    public static readonly B64_BOMB = 'data:image/png;base64,' +
        '';

    public static readonly B64_RAINBOW = 'data:image/png;base64,' +
        '';

    private static imgCache: Map<string, HTMLImageElement> = new Map();
    private static isInitialized = false;

    /**
     * 预热加载所有 AI 图标贴图
     */
    public static init() {
        if (this.isInitialized || typeof Image === 'undefined') return;
        this.isInitialized = true;

        this.loadImage('HORIZONTAL', this.B64_HORIZONTAL);
        this.loadImage('VERTICAL', this.B64_VERTICAL);
        this.loadImage('BOMB', this.B64_BOMB);
        this.loadImage('RAINBOW', this.B64_RAINBOW);
    }

    private static loadImage(key: string, src: string) {
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
            this.imgCache.set(key, img);
        };
        img.src = src;
        if (img.complete) {
            this.imgCache.set(key, img);
        }
    }

    public static getImage(key: 'HORIZONTAL' | 'VERTICAL' | 'BOMB' | 'RAINBOW'): HTMLImageElement | null {
        if (!this.isInitialized) {
            this.init();
        }
        return this.imgCache.get(key) || null;
    }
}
